async function seedQuestions(prismaClient?: PrismaClient) {
  const prisma = prismaClient ?? new PrismaClient();

  try {
    let category = await prisma.category.findUnique({
      where: { slug: CATEGORY_SLUG },
    });

    if (!category) {
      category = await prisma.category.findUnique({
        where: { name: CATEGORY_NAME },
      });
    }

    if (!category) {
      category = await prisma.category.create({
        data: {
          name: CATEGORY_NAME,
          slug: CATEGORY_SLUG,
          group: "Technology",
        },
      });
    } else {
      category = await prisma.category.update({
        where: { id: category.id },
        data: {
          group: "Technology",
        },
      });
    }

    const subcategoryCache = new Map<string, string>();

    for (const item of questions) {
      let subcategoryId = subcategoryCache.get(item.subcategorySlug);

      if (!subcategoryId) {
        const subcategory = await prisma.subcategory.upsert({
          where: {
            categoryId_slug: {
              categoryId: category.id,
              slug: item.subcategorySlug,
            },
          },
          update: {
            name: item.subcategoryName,
          },
          create: {
            categoryId: category.id,
            name: item.subcategoryName,
            slug: item.subcategorySlug,
          },
        });
        subcategoryId = subcategory.id;
        subcategoryCache.set(item.subcategorySlug, subcategory.id);
      }

      // categoryName/categorySlug/subcategoryName/subcategorySlug are content metadata only.
      // InterviewQuestion stores the actual relations through categoryId/subcategoryId.
      const question = await prisma.interviewQuestion.upsert({
        where: { slug: item.slug },
        update: {
          question: item.question,
          categoryId: category.id,
          subcategoryId,
          experienceLevel: item.experienceLevel,
          difficulty: item.difficulty,
          interviewType: item.interviewType,
          shortDescription: item.shortDescription,
          explanation: item.explanation,
          sampleAnswer: item.sampleAnswer,
          detailedAnswer: item.detailedAnswer,
          keyPoints: item.keyPoints,
          commonMistakes: item.commonMistakes,
          followUpQuestions: item.followUpQuestions,
          tags: item.tags,
          isPublished: true,
          seoTitle: item.seoTitle,
          seoDescription: item.seoDescription,
        },
        create: {
          question: item.question,
          slug: item.slug,
          categoryId: category.id,
          subcategoryId,
          experienceLevel: item.experienceLevel,
          difficulty: item.difficulty,
          interviewType: item.interviewType,
          shortDescription: item.shortDescription,
          explanation: item.explanation,
          sampleAnswer: item.sampleAnswer,
          detailedAnswer: item.detailedAnswer,
          keyPoints: item.keyPoints,
          commonMistakes: item.commonMistakes,
          followUpQuestions: item.followUpQuestions,
          tags: item.tags,
          isPublished: true,
          seoTitle: item.seoTitle,
          seoDescription: item.seoDescription,
        },
      });

      console.log(`Inserted/updated: ${question.slug}`);
    }

    console.log(`Successfully seeded ${questions.length} Java interview questions.`);
  } finally {
    if (!prismaClient) {
      await prisma.$disconnect();
    }
  }
}

if (require.main === module) {
  seedQuestions().catch((error) => {
    console.error("Failed to seed interview questions:", error);
    process.exit(1);
  });
}
